"""`.KK Tears`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.KK Tears'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Shader', 'NodeSocketShader')
    t.socket('INPUT', 'Game look', 'NodeSocketFloat', subtype='FACTOR', default_value=1.0, min_value=0.0, max_value=1.0)
    t.socket('INPUT', 'Use HDRI', 'NodeSocketFloat', subtype='FACTOR', default_value=1.0, min_value=0.0, max_value=1.0)
    t.socket('INPUT', 'Tear color', 'NodeSocketColor', default_value=(0.0, 0.80516243, 1.0, 1.0))
    t.socket('INPUT', 'Main', 'NodeSocketColor')
    t.socket('INPUT', 'Hidden', 'NodeSocketFloat', subtype='FACTOR', min_value=0.0, max_value=1.0)

    t.node('NodeFrame', 'Frame', props={
        'location': (-436.0, 845.0),
        'width': 1012.0,
        'height': 634.0,
        'label': 'Use HDRI',
        'color': (0.604, 0.604, 0.604),
    })
